-- Nanocrystal rock pipeline (Carbonrich Rock -> Program Crystal)
-- Source: AO-Universe nanocrystal-creation + AOWiki tool QL floors
-- Safe to re-run: deletes prior AORebirth rock-pipeline rows first
DELETE FROM tradeskill WHERE Id1 BETWEEN 150275 AND 150281 AND Id2 IN (150273,150274);
DELETE FROM tradeskill WHERE Id1 IN (144783,144785,149814,149819,149820,149821,149822) AND Id2 BETWEEN 144767 AND 144770;
DELETE FROM tradeskill WHERE Id1 IN (144784,144786,149815,149816,149817,149818,149823) AND Id2 IN (144799,144800);
SELECT COUNT(*) AS rock_pipeline_rows FROM tradeskill WHERE (Id1 BETWEEN 150275 AND 150281 AND Id2 IN (150273,150274)) OR (Id1 IN (144783,144785,149814,149819,149820,149821,149822) AND Id2 BETWEEN 144767 AND 144770) OR (Id1 IN (144784,144786,149815,149816,149817,149818,149823) AND Id2 IN (144799,144800));
